export const BY_ID = new Map(BLOCKS.map(b => [b.id, b]));
export function colourOf(id){
  const b = BY_ID.get(id); if (b) return b.c;
  const base = id.split("[")[0]; const c = BY_ID.get(base); if (c) return c.c;
  return "#8A8A8A";
}
